@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix bfo: <http://purl.obolibrary.org/obo/> .


sdk:org-001 a iof-core:Manufacturer ;
  rdfs:label "Company A" ;
  sdk:hasNumberOfEmployees "100"^^xsd:string ;
  sdk:hasCertificate sdk:cert-001 ,sdk:cert-002 ;
  sdk:suppliesToIndustry sdk:industry-001, sdk:industry-002 ;
  sdk:hasProcessCapability sdk:org-001-cap-machining, sdk:org-001-cap-coating ;
  sdk:hasMaterialCapability sdk:org-001-mat-bronze, sdk:org-001-mat-steel ;
