  sdk:manufactures sdk:prod-001, sdk:prod-002 ;
  iof-core:describedBy sdk:org-001-description .

sdk:industry-001 a sdk:RenewableEnergyIndustry ;
  rdfs:label "Industry A" .

sdk:industry-002 a sdk:UtilitiesIndustry ;
  rdfs:label "Industry B" .

# --- Process capabilities (2) ---
sdk:org-001-cap-machining a sdk:MachiningCapability ;
  rdfs:label "Machining" .

sdk:org-001-cap-coating a sdk:CoatingCapability ;
  rdfs:label "Coating" .

# --- Material capabilities (2) ---
