  rdfs:label "Bronze" .

sdk:org-001-mat-steel a sdk:SteelProcessingCapability ;
  rdfs:label "Steel" .

# --- NAICS ---
sdk:naics-332996.0-inst a sdk:NAICS332996.0 ;
  sdk:hasNAICSCodeValue "332996.0"^^xsd:integer ;
  sdk:hasNAICSTextValue "FABRICATED PIPE AND PIPE FITTING MANUFACTURING" .

# --- Site / location (anonymized) ---
sdk:site-001 a sdk:GeospatialLocation ;
  sdk:hasSpatialCoordinates sdk:site-001-coordinates ;
  sdk:locatedInCity sdk:city-001 ;
  sdk:hasZIPcode sdk:site-001-zip ;
  sdk:hasPostalAddress sdk:site-001-address .

sdk:site-001-coordinates a sdk:TwoDimensionalCartesianSpatialCoordinateDatum ;
  sdk:hasLatitudeValue "0.0000000" ;
  sdk:hasLongitudeValue "0.0000000" .

sdk:city-001 a sdk:City ;
  sdk:locatedInState sdk:state-001 ;
  rdfs:label "City A" .

sdk:state-001 a sdk:State ;
  rdfs:label "State A" .

sdk:site-001-zip a sdk:USPostalCode ;
  sdk:hasIntegerValue "00000" .

sdk:site-001-address a sdk:PostalAddress ;
  iof-scro:hasTextValue "Address Line 1" .

# --- Products (2) ---
sdk:prod-001 a iof-core:MaterialProduct ; rdfs:label "Product 1" .
sdk:prod-002 a iof-core:MaterialProduct ; rdfs:label "Product 2" .

# --- Cert & description ---
sdk:cert-001 a sdk:ISO9001 ;
  rdfs:label "ISO 9001" .

sdk:cert-002 a sdk:ISO14001 ;
  rdfs:label "ISO 14001" .

sdk:org-001-description a sdk:BusinessDescription .
  iof-scro:hasTextValue "This is a sample business description for Company A." .
